# Test fmristore adapter integration
# These tests use synthetic test fixtures generated by helpers-generate-test-fixtures.R

test_that("fmristore test fixtures exist or can be generated", {
  skip_if_not_installed("neuroim2")
  skip_if_not_installed("fmristore")
  skip_if_not_installed("hdf5r")

  testdata_dir <- test_path("testdata")

  # Check if fixtures exist, generate if not
  fixtures <- list(
    labeled_volume = file.path(testdata_dir, "labeled_volume_small.h5"),
    parcellated = file.path(testdata_dir, "parcellated_small.h5"),
    latent_vec = file.path(testdata_dir, "latent_vec_small.lv.h5")
  )

  # Generate missing fixtures
  if (!all(file.exists(unlist(fixtures)))) {
    message("\nGenerating missing test fixtures...")
    source(test_path("helpers-generate-test-fixtures.R"))
    generate_all_fmristore_fixtures()
  }

  # Verify all exist
  expect_true(file.exists(fixtures$labeled_volume))
  expect_true(file.exists(fixtures$parcellated))
  expect_true(file.exists(fixtures$latent_vec))
})


test_that("fmristore adapter detects LabeledVolumeSet layout", {
  skip_if_not_installed("neuroim2")
