test_that("fmristore adapter closes handles properly", {
  skip_if_not_installed("neuroim2")
  skip_if_not_installed("fmristore")
  skip_if_not_installed("hdf5r")

  fixture <- test_path("testdata/labeled_volume_small.h5")
  skip_if_not(file.exists(fixture), "Test fixture not available")

  handle <- .fmri_open(fixture, mode = "r")

  # Close should work without error
  expect_silent(.fmri_close(handle))

  # Handle should no longer be valid
  expect_false(handle$h5$is_valid)
})


test_that("fmristore adapter handles /gds group (Path B)", {
  skip_if_not_installed("hdf5r")

  # Create a temporary file with /gds group
  tmpfile <- tempfile(fileext = ".h5")
  on.exit(unlink(tmpfile))

  h5 <- hdf5r::H5File$new(tmpfile, mode = "w")
  h5$create_group("/gds")
  h5$close_all()

  # Should detect as score 1.0 (delegates to h5 adapter)
  score <- .fmri_detect(tmpfile)
  expect_equal(score, 1.0)
})
